{
  "schema_version": 1,
  "suite_id": "correlation_admission_golden",
  "fixture_root": "tests/fixtures/product_truth/correlation_admission_golden",
  "capability_assertions": [
    {
      "capability": "admission_decisions.golden_audit",
      "surfaces": ["reducer", "graph", "api", "mcp"],
      "positive": "Admitted service, package, and cloud/resource correlation decisions carry explanation evidence and agree with graph and readback truth.",
      "negative": "Rejected and missing-evidence decisions remain provenance-only and never publish canonical graph facts.",
      "ambiguous": "Ambiguous and stale replay cases stay visible without being promoted to current canonical graph truth."
    }
  ],
  "fixture_intents": [
    {
      "case_id": "deployable-service-admitted",
      "domain": "deployable_unit_correlation",
      "scope_id": "git-repository-scope:team/api",
      "generation_id": "generation-current",
      "expected_state": "admitted",
      "expected_graph_facts": [
        {
          "case_id": "deployable-service-admitted",
          "kind": "relationship",
          "id": "CORRELATES_DEPLOYABLE_UNIT:repo://team/api:service://team/api"
        }
      ],
      "fixture_intent": "deployable-service-admitted expects one explicit service/deployment graph relationship with reducer admission evidence"
    },
    {
      "case_id": "deployable-service-missing-evidence",
      "domain": "deployable_unit_correlation",
      "scope_id": "git-repository-scope:team/worker",
      "generation_id": "generation-current",
      "expected_state": "missing_evidence",
      "fixture_intent": "deployable-service-missing-evidence expects a service candidate without deployment repository evidence to stay provenance-only"
    },
    {
      "case_id": "package-source-admitted",
      "domain": "package_source_correlation",
      "scope_id": "package-registry:npm:team-api",
      "generation_id": "generation-current",
      "expected_state": "admitted",
      "expected_graph_facts": [
        {
          "case_id": "package-source-admitted",
          "kind": "package_consumption",
          "id": "package-consumption:repo://team/consumer:pkg:npm/team-api"
        }
      ],
      "fixture_intent": "package-source-admitted expects manifest dependency evidence to publish one package consumption truth row"
    },
    {
      "case_id": "package-source-ambiguous",
      "domain": "package_source_correlation",
      "scope_id": "package-registry:npm:team-api",
      "generation_id": "generation-current",
      "expected_state": "ambiguous",
      "fixture_intent": "package-source-ambiguous expects conflicting source hints to stay visible without ownership promotion"
    },
    {
      "case_id": "package-source-stale-replay",
      "domain": "package_source_correlation",
      "scope_id": "package-registry:npm:team-api",
      "generation_id": "generation-previous",
      "expected_state": "stale",
      "fixture_intent": "package-source-stale-replay expects an older package-source generation to stay stale and never appear as current admitted truth"
    },
    {
      "case_id": "cloud-resource-admitted",
      "domain": "cloud_inventory_admission",
      "scope_id": "cloud:gcp:team",
      "generation_id": "generation-current",
      "expected_state": "admitted",
      "expected_graph_facts": [
        {
          "case_id": "cloud-resource-admitted",
          "kind": "cloud_resource",
          "id": "cloud-resource:gcp:team:api-instance"
        }
      ],
      "fixture_intent": "cloud-resource-admitted expects supported cloud inventory identity to publish one canonical cloud resource"
    },
    {
      "case_id": "cloud-resource-rejected",
      "domain": "cloud_inventory_admission",
      "scope_id": "cloud:gcp:team",
      "generation_id": "generation-current",
      "expected_state": "rejected",
      "fixture_intent": "cloud-resource-rejected expects unsafe or conflicting cloud identity evidence to remain provenance-only"
    }
  ]
}

{
  "schema_version": 1,
  "suite_id": "correlation_dsl",
  "fixture_root": "tests/fixtures/correlation_dsl",
  "capability_assertions": [
    {
      "capability": "deployable_unit.correlation",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "Service repositories with explicit delivery evidence are admitted as deployable units.",
      "negative": "Utility or ambiguous multi-Dockerfile repositories remain provenance-only unless stronger evidence exists."
    },
    {
      "capability": "delivery.github_actions",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "GitHub Actions workflow checkout and reusable workflow evidence resolves to repository relationships."
    },
    {
      "capability": "delivery.jenkins",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "Jenkinsfile controller artifacts surface in repository context and story responses."
    },
    {
      "capability": "delivery.ansible",
      "surfaces": ["api", "content", "postgres"],
      "positive": "Jenkins-to-Ansible handoff preserves playbook, inventory, group vars, host vars, and role hints."
    },
    {
      "capability": "delivery.docker_compose",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "Compose build, image, ports, and depends_on evidence surface without upgrading local runtime evidence to production deployment truth."
    },
    {
      "capability": "delivery.argocd",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "ArgoCD Application evidence links service repositories to deployment repositories and shared config."
    },
    {
      "capability": "delivery.terraform",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "Terraform stack evidence resolves module and service relationships without relying on repo-name coincidence."
    }
  ]
}

{
  "schema_version": 1,
  "suite_id": "graph_analysis",
  "fixture_root": "tests/fixtures/graph_analysis_compose",
  "capability_assertions": [
    {
      "capability": "call_graph.direct_callers",
      "surfaces": ["api", "graph"],
      "positive": "persistGraphProof has dispatchGraphProof as its direct caller.",
      "negative": "deadAlphaGraphProof has no inbound CALLS, IMPORTS, or REFERENCES edges."
    },
    {
      "capability": "call_graph.transitive_callers",
      "surfaces": ["api", "graph"],
      "positive": "persistGraphProof has a depth-aware caller chain through dispatchGraphProof, entrypointGraphProof, and main."
    },
    {
      "capability": "call_graph.call_chain_path",
      "surfaces": ["api", "graph"],
      "positive": "entrypointGraphProof resolves to persistGraphProof through the expected shortest path."
    },
    {
      "capability": "code_quality.dead_code",
      "surfaces": ["api", "graph", "content"],
      "positive": "Only the intentionally unused fixture functions are returned as dead-code candidates.",
      "truth_level": "derived"
    }
  ]
}

{
  "schema_version": 1,
  "suite_id": "relationship_platform",
  "fixture_root": "tests/fixtures/relationship_platform",
  "capability_assertions": [
    {
      "capability": "relationship_evidence.mapping",
      "surfaces": ["graph", "postgres", "api"],
      "positive": "Repository edges expose resolved_id, generation_id, evidence_count, evidence_kinds, confidence, and rationale pointers.",
      "negative": "No canonical repository relationship is accepted without evidence rows."
    },
    {
      "capability": "repository.relationship_overview",
      "surfaces": ["api", "graph"],
      "positive": "Repository context partitions controller-driven, workflow-driven, IaC-driven, and other typed relationships."
    },
    {
      "capability": "repository.deployment_artifacts",
      "surfaces": ["api", "content"],
      "positive": "Repository story and context preserve workflow artifacts, controller artifacts, Docker, Helm, Kustomize, CloudFormation, and config artifacts."
    },
    {
      "capability": "repository.api_surface",
      "surfaces": ["api", "graph", "content"],
      "positive": "Framework routes and endpoint surfaces are visible for service repositories with route evidence."
    },
    {
      "capability": "service.deployment_trace",
      "surfaces": ["api", "graph", "postgres"],
      "positive": "Service deployment trace connects service, delivery evidence, IaC evidence, platforms, and environments without fabricating missing runtime truth."
    }
  ]
}

{
  "schema_version": 1,
  "capability": "iac_quality.dead_iac",
  "status": "planned",
  "definition": "IaC artifacts or definitions that are not reachable from same-repo references, cross-repo references, CI/CD workflows, deployment controllers, or deployment roots.",
  "fixture_root": "tests/fixtures/product_truth/dead_iac",
  "expected_truth_file": "tests/fixtures/product_truth/expected/dead_iac.json",
  "families": [
    {
      "family": "terraform",
      "positive_cases": [
        "local module referenced by module.source",
        "module repository referenced by a cross-repo Terraform or Terragrunt source"
      ],
      "negative_cases": [
        "local module directory with no same-repo or cross-repo reference"
      ],
      "ambiguous_cases": [
        "dynamic module source built from variables or helper expressions",
        "remote source that does not resolve to an indexed repository"
      ]
    },
    {
      "family": "helm",
      "positive_cases": [
        "chart reached by ArgoCD Application or ApplicationSet source",
        "chart reached by workflow helm command",
        "chart reached by Kustomize helmCharts reference"
      ],
      "negative_cases": [
        "chart directory with no controller, workflow, or local reference"
      ],
      "ambiguous_cases": [
        "templated chart path",
        "values-driven chart reference that cannot be resolved statically"
      ]
    },
    {
      "family": "kustomize",
      "positive_cases": [
        "overlay reached by ArgoCD Application source path",
        "base reached by kustomization resources"
      ],
      "negative_cases": [
        "base or overlay directory with no ArgoCD, ApplicationSet, or kustomization reference"
      ],
      "ambiguous_cases": [
        "templated ArgoCD source path",
        "variable-selected kustomization resource path"
      ]
    },
    {
      "family": "ansible",
      "positive_cases": [
        "role referenced by a playbook",
        "playbook invoked by Jenkins or GitHub Actions"
      ],
      "negative_cases": [
        "role directory with no playbook import/include and no controller invocation",
        "playbook file with no workflow/controller/root reference"
      ],
      "ambiguous_cases": [
        "dynamic role name from vars",
        "external collection role that is not expected to resolve to a local repo artifact"
      ]
    },
    {
      "family": "compose",
      "positive_cases": [
        "service reached by Docker Compose workflow command",
        "service reached by Docker Compose controller command"
      ],
      "negative_cases": [
        "compose service with no workflow or controller reference"
      ],
      "ambiguous_cases": [
        "dynamic service name selected from workflow or controller variables"
      ]
    }
  ],
  "required_truth_surfaces": [
    "graph or materialized usage edges",
    "Postgres evidence rows explaining each finding",
    "API /api/v0/iac/dead with truth envelope and limitations",
    "MCP find_dead_iac tool after API contract is proven"
  ]
}

