# Bucket A: drift_added_in_state — config has the s3 backend block only;
# no resource block for aws_s3_bucket.unmanaged. The state file at
# s3://eshu-drift-a/prod/terraform.tfstate carries that resource, so the
# drift handler should emit drift_kind="added_in_state".

terraform {
  backend "s3" {
    bucket = "eshu-drift-a"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

# Bucket B: drift_added_in_config — config declares aws_s3_bucket.declared
# but the state at s3://eshu-drift-b/prod/terraform.tfstate is empty of
# resources. The drift handler should emit drift_kind="added_in_config".

terraform {
  backend "s3" {
    bucket = "eshu-drift-b"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

resource "aws_s3_bucket" "declared" {
  acl = "private"
}

# Bucket D, repo "a": ambiguous-owner pair — this repo and drift-d-tf-config-b
# both declare the same s3 backend at s3://eshu-drift-d/prod/terraform.tfstate.
# The drift handler's resolver should return ErrAmbiguousBackendOwner and emit
# a WARN log with failure_class="ambiguous_backend_owner". No counter delta.

terraform {
  backend "s3" {
    bucket = "eshu-drift-d"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

# Bucket D, repo "b": ambiguous-owner pair sibling of drift-d-tf-config-a.
# Both repos declare the same s3 backend at s3://eshu-drift-d/prod/terraform.tfstate
# so the resolver must reject as ambiguous. No counter delta expected.

terraform {
  backend "s3" {
    bucket = "eshu-drift-d"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

# Bucket E: attribute_drift — both config and state declare aws_s3_bucket.logs.
# Config carries SSE algorithm AES256; the state at
# s3://eshu-drift-e/prod/terraform.tfstate carries the same key wrapped in the
# Terraform-state nested-singleton-array shape resolving to aws:kms. The acl
# value matches on both sides (private) so only the SSE path drifts.

terraform {
  backend "s3" {
    bucket = "eshu-drift-e"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

resource "aws_s3_bucket" "logs" {
  acl = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Bucket C gen-1: drift_removed_from_state — gen-1 state has aws_s3_bucket.cached,
# gen-2 state has the same lineage with serial=2 and the resource removed. The
# loader's priorStateSnapshotMetadataQuery
# (go/internal/storage/postgres/tfstate_drift_evidence_sql.go line 135) selects the
# prior generation by `serial = currentSerial - 1` on the same lineage, so when
# Phase 3.5 fires for the gen-2 snapshot it finds gen-1 as the prior and emits
# drift_kind="removed_from_state" for aws_s3_bucket.cached.
#
# Config does not change between generations; only the state file changes.

terraform {
  backend "s3" {
    bucket = "eshu-drift-c"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

resource "aws_s3_bucket" "cached" {
  acl = "private"
}

# Bucket C gen-2: identical config to gen-1. Only the state file rotates to
# serial=2 with the resource removed; see ../../state_gen2/drift-c.tfstate.

terraform {
  backend "s3" {
    bucket = "eshu-drift-c"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

resource "aws_s3_bucket" "cached" {
  acl = "private"
}

# Bucket F gen-2: same backend, resource removed from config. The Tier-2 v2.5
# verifier runs collector-instance-2 against this gen-2 tree after instance-1
# already collected the gen-1 tree, so Postgres has both an active gen-2
# scope_generations row (without the resource) and a superseded gen-1 row
# (with the resource) on the same repo scope_id.

terraform {
  backend "s3" {
    bucket = "eshu-drift-f"
    key    = "prod/terraform.tfstate"
    region = "us-east-1"
  }
}

